/**
 * Identifiers.
 *
 * Bid idempotency keys are generated by the CLIENT, one per bid attempt, so that
 * a retry, a double tap or a socket reconnect cannot create a second bid.
 * See docs/MILESTONE-1-DESIGN.md §7.8.
 */

import { z } from 'zod';

export const idempotencyKeySchema = z
  .string()
  .uuid('An idempotency key must be a UUID generated by the client');

export type IdempotencyKey = z.infer<typeof idempotencyKeySchema>;

export function newIdempotencyKey(): IdempotencyKey {
  return crypto.randomUUID();
}

/** A request/bid correlation id that appears in every log line for one bid. */
export function newTraceId(): string {
  return crypto.randomUUID().replaceAll('-', '').slice(0, 16);
}
